<script setup>
import { ref,computed,onMounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { catalogoService } from '@/services/catalogo.service'
import { movimientosService } from '@/services/movimientos.service'
const route=useRoute(),router=useRouter()
const type=computed(()=>route.meta.movementType)
const titles={entry:'Entrada de inventario',exit:'Salida de inventario',transfer:'Traslado entre sucursales'}
const branches=ref([]),products=ref([]),locations=ref([]),error=ref(''),notice=ref(''),busy=ref(false)
const data=ref({branch_id:'',source_branch_id:'',target_branch_id:'',supplier_name:'',reference_code:'',customer_reference:'',reason:'sale',notes:'',items:[]})
const originBranch=computed(()=>type.value==='transfer'?data.value.source_branch_id:data.value.branch_id)
const sourceLocations=computed(()=>locations.value.filter(l=>String(l.branch_id)===String(originBranch.value)))
const targetLocations=computed(()=>locations.value.filter(l=>String(l.branch_id)===String(data.value.target_branch_id)))
function addItem(){data.value.items.push({product_id:'',location_id:'',source_location_id:'',target_location_id:'',quantity:1,unit_cost:''})}
addItem()
const unwrap=(res)=>res?.data??[]
onMounted(async()=>{try{const results=await Promise.all([catalogoService.list('branches'),catalogoService.list('products'),catalogoService.list('locations')]);[branches.value,products.value,locations.value]=results.map(unwrap)}catch(e){error.value='No se pudieron cargar los catálogos: '+e.message}})
function validate(){if(type.value==='transfer'&&String(data.value.source_branch_id)===String(data.value.target_branch_id))return 'Las sucursales de origen y destino deben ser diferentes';const seen=new Set();for(const item of data.value.items){const key=[item.product_id, type.value==='transfer'?item.source_location_id:item.location_id,type.value==='transfer'?item.target_location_id:''].join(':');if(seen.has(key))return 'No se puede repetir la misma combinación de producto y ubicaciones';seen.add(key)}return ''}
async function submit(){error.value='';notice.value='';const issue=validate();if(issue){error.value=issue;return}busy.value=true;try{const items=data.value.items.map(i=>{const item={product_id:Number(i.product_id),quantity:Number(i.quantity)};if(type.value==='transfer'){item.source_location_id=Number(i.source_location_id);item.target_location_id=Number(i.target_location_id)}else{item.location_id=Number(i.location_id);if(type.value==='entry'&&i.unit_cost!=='')item.unit_cost=Number(i.unit_cost)}return item})
 const payload={items,notes:data.value.notes||null,reference_code:data.value.reference_code||null}
 if(type.value==='transfer'){payload.source_branch_id=Number(data.value.source_branch_id);payload.target_branch_id=Number(data.value.target_branch_id)}else{payload.branch_id=Number(data.value.branch_id);if(type.value==='entry')payload.supplier_name=data.value.supplier_name;else{payload.reason=data.value.reason;payload.customer_reference=data.value.customer_reference||null}}
 await movimientosService.submit(type.value,payload);notice.value='Movimiento registrado correctamente';data.value.items=[];addItem()}catch(e){error.value=e.data?.message||e.message;if(e.data?.errors)error.value+=': '+Object.values(e.data.errors).flat().join('; ')}finally{busy.value=false}}
</script>
<template><section><h2>{{titles[type]}}</h2><p>Completa los datos obligatorios. Los movimientos actualizan el inventario real.</p><form class="panel" @submit.prevent="submit"><div class="grid"><label v-if="type!=='transfer'">Sucursal<select v-model="data.branch_id" required><option value="">Seleccionar</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label><template v-else><label>Sucursal origen<select v-model="data.source_branch_id" required><option value="">Seleccionar</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label>Sucursal destino<select v-model="data.target_branch_id" required><option value="">Seleccionar</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label></template><label v-if="type==='entry'">Proveedor<input v-model.trim="data.supplier_name" required maxlength="150" /></label><label v-if="type==='exit'">Motivo<select v-model="data.reason" required><option value="sale">Venta</option><option value="damaged">Dañado</option><option value="internal_use">Uso interno</option></select></label><label v-if="type==='exit'">Referencia de cliente<input v-model.trim="data.customer_reference" maxlength="150" /></label><label>Referencia<input v-model.trim="data.reference_code" maxlength="100" /></label></div><h3>Productos del movimiento</h3><div v-for="(item,index) in data.items" :key="index" class="item"><label>Producto<select v-model="item.product_id" required><option value="">Seleccionar</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.sku}} — {{p.name}}</option></select></label><label v-if="type!=='transfer'">Ubicación<select v-model="item.location_id" required><option value="">Seleccionar</option><option v-for="l in sourceLocations" :key="l.id" :value="l.id">{{l.code}} · {{l.shelf}}/{{l.level}}/{{l.bin}}</option></select></label><template v-else><label>Ubicación origen<select v-model="item.source_location_id" required><option value="">Seleccionar</option><option v-for="l in sourceLocations" :key="l.id" :value="l.id">{{l.code}}</option></select></label><label>Ubicación destino<select v-model="item.target_location_id" required><option value="">Seleccionar</option><option v-for="l in targetLocations" :key="l.id" :value="l.id">{{l.code}}</option></select></label></template><label>Cantidad<input v-model.number="item.quantity" required type="number" min="1" step="1"/></label><label v-if="type==='entry'">Costo unitario (opcional)<input v-model="item.unit_cost" type="number" min="0" step="0.01"/></label><button type="button" class="remove" :disabled="data.items.length===1" @click="data.items.splice(index,1)">Quitar línea</button></div><button type="button" class="subtle" @click="addItem">+ Agregar producto</button><label>Observaciones<textarea v-model="data.notes" maxlength="1000" rows="3"></textarea></label><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><div class="actions"><button type="button" class="subtle" @click="router.push('/almacen')">Regresar</button><button type="submit" class="primary" :disabled="busy">{{busy?'Guardando...':'Registrar movimiento'}}</button></div></form></section></template>
<style scoped>h2{color:#14243a}p{color:#64748b}.panel{background:#fff;border:1px solid #e2e8f0;padding:24px;border-radius:12px;display:grid;gap:16px}.grid,.item{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.item{padding:16px;border:1px solid #e2e8f0;border-radius:10px;background:#f8fafc}label{display:grid;gap:7px;font-weight:600;color:#334155;font-size:14px}input,select,textarea{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;font:inherit}button{padding:10px 15px;border-radius:8px;cursor:pointer;border:1px solid #cbd5e1}.primary{background:#2563eb;color:white;border-color:#2563eb}.subtle{background:#fff;color:#334155}.remove{color:#be123c;background:#fff}.actions{display:flex;justify-content:flex-end;gap:10px}.error{color:#b91c1c}.success{color:#047857}</style>
